function TestSimulateNoLag:Run()
    local reimport = function(name)
        package.loaded[name] = nil
        package.preload[name] = nil
        local env = (_G or _ENV)
        env[name] = nil
        return import(name)
    end

    local initData = table.deserialize(singleInitData).initData
    -- local initData = table.deserialize(multiServerData).initDatas[1]

    BattleInfo = reimport("Game.BattleView.Core.BattleInfo")
    BattleInfo = BattleInfo.New(Constants.GameMode.PVP, Constants.PlayMode.Battle, Constants.PVPMode.None, Constants.InputMode.AutoNoLag, initData, nil, 0)
    BattleInfo.HandleInitData(initData)

    ---@type BattleMgr
    BattleMgr = reimport("Game.Battle.Core.BattleMgr")
    BattleMgr:Init(initData)
    BattleMgr:GameStart()

    RecordMgr:SaveRecord()

    collectgarbage("collect")
end

return TestSimulateNoLag